-- ============================================================
-- Этап 2 «Пол» эталона Homesteader's Cabin: тексты шагов 1–3 сверены с
-- ведомостью материалов (спека 007, поправки после закрытия 2026-09-28).
-- Источник текстов — ЭТАП2_Пол.md.
--   Шаг 1: рама в два слоя на всех четырёх сторонах (двойная линия на
--          Floor Framing, с. 3), сшивка слоёв, рама к опорным балкам —
--          длинными саморезами наискосок.
--   Шаг 2: лаги только на подвесах, подвес — ершёными гвоздями по схеме
--          производителя, подвес под сухую доску 45 мм.
--   Шаг 3: черновые бруски поперёк балок, минвата 200 мм на 5 см ниже
--          верха, лента на стыках пароизоляции.
-- Только update по изменённым полям: шаги не удаляются (на них ссылаются
-- отметки прогресса), id и sort не меняются. Шаг 4 не трогается.
-- Идемпотентно. Без этапа 312 — тихо пропуск (как 017).
-- ============================================================

do $do$
begin
  if not exists (select 1 from stages
                 where id = 'de300000-0000-4000-8000-000000000312') then
    return;
  end if;

  update steps set
    why_text = 'Сначала собираем «периметр» — прямоугольную рамку из толстых досок по краю. Рама у нас двойная: на каждой стороне по две доски, сшитые вместе, — так на чертеже, и так крепче. Это скелет, к которому потом крепятся все остальные балки. От того, насколько ровный этот прямоугольник, зависит весь дом.',
    prep_text = 'Купи заранее (из сметы): доски 50×250 мм на раму — по две на каждую сторону; гвозди 90 мм; длинные саморезы по дереву 6×140 мм — крепить раму к опорным балкам (насадку к шуруповёрту под их головку купи там же).',
    actions = '["Дом у нас 3,66 м в ширину и 7,32 м в длину. Рама — в два слоя: на каждой стороне по две доски 50×250 «на ребро» (высокой стороной вверх). Сначала собери первое кольцо на опорных балках, которые уложил в Этапе 1: две длинные доски по 7,32 м — отступив 5 см от наружного края балок (туда потом встанет второй слой), — и между ними две короткие по 3,46 м.","Длинная сторона — из двух кусков: доска 6 м и вставка 1,32 м. Соедини углы кольца: приставь торец короткой доски к боку длинной и забей 3 гвоздя 90 мм в каждый угол.","Проверь диагонали! Измерь рамку из угла в угол крест-накрест. Обе диагонали должны совпасть (разница ≤5 мм) — тогда прямоугольник ровный. Если не совпали — двигай раму, пока не сравняются.","Второй слой: к каждой длинной стороне снаружи приложи ещё одну доску, к каждой короткой — изнутри. Стык второго слоя делай у другого конца дома, чтобы он не пришёлся напротив стыка первого. Углы второго слоя — тоже по 3 гвоздя.","Сшей слои — то есть сбей две доски в одну толстую: гвозди 90 мм через каждые 40 см, по 2 (один выше, другой ниже) на всех четырёх сторонах.","Прикрепи раму к опорным балкам длинными саморезами 6×140: вкручивай их наискосок — под углом примерно 45°, от низа доски рамы вниз в балку. Через каждые 60 см по обеим длинным сторонам."]',
    tools = '{"молоток","шуруповёрт","рулетка 10 м","угольник","уровень","карандаш"}',
    self_check = '["Рама 3,66 × 7,32 м собрана в два слоя, доски на ребре","Углы скреплены (по 3 гвоздя в каждом слое)","Диагонали совпали (разница ≤5 мм)","Слои сшиты гвоздями через 40 см, стыки слоёв не напротив друг друга","Рама прикручена к опорным балкам саморезами наискосок через 60 см"]',
    hint = 'Доски 50×250 длинные и тяжёлые. Ставь их на ребро (высокой стороной вверх) — так они держат нагрузку. Плашмя класть нельзя, прогнутся. Гвозди сшивки ставь один выше, другой ниже, а не в одну линию — так доска не треснет.'
  where id = 'de300000-0000-4000-8000-000000000431';

  update steps set
    title = 'Ставим лаги (балки пола)',
    why_text = 'Внутри рамы через равные промежутки ставим поперечные балки, на которые ляжет настил. Их называют лагами (это просто балки пола). Чем чаще они стоят, тем крепче пол и тем меньше он «играет» под ногами.',
    prep_text = 'Купи заранее (из сметы): доски 50×250 мм — длиной по ширине дома, 3,46 м между рамой; подвесы (стальные «карманы» для концов балок) — по два на каждую балку; ершёные гвозди 4×40 для подвесов. Если доска сухая строганая, она тоньше — 45 мм, и подвес для неё свой, шириной 45 мм (в смете он подставится сам, если выбрана сухая доска).',
    actions = '["Размечай на раме места балок: они ставятся через каждые 61 см (это шаг 610 мм — стандарт, лист настила ровно ляжет краями). Отметь карандашом на обеих длинных сторонах рамы.","На каждую метку поставь подвес (стальной «карман» для конца балки) так, чтобы балка в нём встала вровень с верхом рамы.","Прибей подвес ершёными гвоздями 4×40 (ершёный гвоздь — с насечками, держит крепче обычного) по схеме производителя подвеса — она на упаковке или на сайте. Для доски тоньше 6 см гвозди ставят не во все отверстия, а примерно в половину — иначе доска треснет.","Вставь балку 50×250 в подвесы с обеих сторон, на ребро, и прибей её к подвесу по той же схеме. Балку крепи только на подвесах — гвозди наискосок вместо подвеса не годятся.","Проверь уровнем, что все балки вровень — по ним пойдёт ровный настил."]',
    tools = '{"молоток","рулетка 10 м","карандаш","уровень"}',
    self_check = '["Места балок размечены через 61 см","Все балки стоят в подвесах с обоих концов","Подвесы прибиты ершёными гвоздями по схеме производителя","Балки вровень с верхом рамы (проверено уровнем)"]',
    hint = 'Шаг 61 см выбран не случайно — это чтобы стандартный лист фанеры (122 см) лёг ровно краями на балки. Не меняй шаг, иначе настил повиснет в воздухе. Сухая строганая доска тоньше обычной — 45 мм вместо 50: для неё бери подвес шириной 45 мм, в широком она будет болтаться.',
    common_mistake = 'Ставить балки «примерно», на глаз. Тогда край фанеры попадёт мимо балки, пол будет прогибаться. Меряй каждую по метке.'
  where id = 'de300000-0000-4000-8000-000000000432';

  update steps set
    why_text = 'Между балками пола укладываем утеплитель — иначе через пол будет тянуть холодом снизу, а зимой пол будет ледяным. В США этот дом строят без утепления (тёплый климат), но для нас это обязательно.',
    prep_text = 'Купи заранее (из сметы): минеральную вату плитами 100 мм — в два слоя; ветрозащитную плёнку (снизу) и пароизоляционную (сверху); соединительную ленту для стыков пароизоляции; черновые бруски 50×50 мм — держать утеплитель снизу; гвозди 90 мм.',
    actions = '["Снизу на балки натяни ветрозащитную плёнку: полотна внахлёст на 10–15 см, прихвати степлером.","Поверх плёнки, поперёк балок — вдоль дома — прибей черновые бруски 50×50: 5 рядов через 58 см по ширине, у самой рамы ряд не нужен. Стыки брусков делай только на балке. В каждую балку — по гвоздю 90 мм, на стыке — по гвоздю в конец каждого бруска. Бруски держат плёнку и утеплитель, чтобы не выпали.","Уложи плиты минваты между балками в два слоя по 100 мм, плотно, без щелей (в щели уходит тепло). Толщина ~200 мм — на 5 см ниже верха лаги (балки пола): этот зазор оставь пустым.","Сверху накрой пароизоляционной плёнкой (не даёт влаге из дома мочить утеплитель): три полосы вдоль дома внахлёст на 10–15 см, прихвати степлером. Стыки проклей соединительной лентой по всей длине."]',
    tools = '{"степлер строительный","нож","молоток","рулетка 10 м"}',
    self_check = '["Снизу натянута ветрозащита, бруски прибиты, утеплитель не выпадает","Минвата в два слоя, плотно, без щелей (~200 мм, на 5 см ниже верха балок)","Сверху пароизоляция, стыки проклеены лентой"]',
    hint = 'Утеплитель кроит легко — обычным ножом или ножовкой. Режь чуть шире промежутка (на 1-2 см), чтоб вставал враспор и не оставлял щелей. Швы второго слоя смещай относительно первого — так холоду негде пройти.'
  where id = 'de300000-0000-4000-8000-000000000433';
end
$do$;
